  ncf[6 * kd + 1] = 1; // H

  // CH3COCH2O
  ncf[7 * kd + 0] = 3; // C
  ncf[7 * kd + 1] = 5; // H
  ncf[7 * kd + 3] = 2; // O

  // C3H5O
