  W += c[62] * 5.8080000000000005e+01;  // C3H6O1-2
  W += c[63] * 4.5016999999999996e+01;  // OCHO
  W += c[64] * 5.9043999999999997e+01;  // CH3CO2
  W += c[65] * 6.0052000000000000e+01;  // CH3OCHO
  W += c[66] * 5.8080000000000005e+01;  // C3H6O1-3
  W += c[67] * 6.4039999999999992e+01;  // HOCH2O2H
  W += c[68] * 4.6069000000000003e+01;  // C2H5OH
  W += c[69] * 5.9043999999999997e+01;  // CH3OCO
  W += c[70] * 9.0078000000000003e+01;  // C3KET12
  W += c[71] * 6.3031999999999996e+01;  // HOCH2O2
  W += c[72] * 4.5061000000000000e+01;  // C2H5O
  W += c[73] * 5.9043999999999997e+01;  // CH2OCHO
  W += c[74] * 9.0078000000000003e+01;  // C3KET13
